INSERT INTO travel_quest_templates (template_key, family, tier, pack_slug, definition) VALUES ($DQ$deliver_borrowed_idiom$DQ$, $DQ$deliver$DQ$, 1, $DQ$drift_p0c_seed$DQ$, $JB${"cargo": {"family": "idiome", "vector": "language"}, "effects": [{"kind": "emit_fragment", "text_de": "Ich habe ein Idiom über den Drift getragen, das sich nicht übersetzen lässt. Unterwegs ertappte ich mich, wie ich in einer Sprache dachte, die ich nie gelernt habe.", "text_en": "I carried an idiom across the Drift that cannot be translated. On the way I caught myself thinking in a language I never learned."}, {"kind": "emit_echo", "text_de": "Ein verklingendes Echo streift {sim}. Ein Satz, den niemand hier sprechen kann, hängt einen Moment in der Luft.", "text_en": "A fading echo brushes {sim}. A sentence no one here can speak hangs in the air for a moment.", "title_de": "Echo aus dem Drift", "title_en": "Echo from the Drift"}, {"importance": 4, "kind": "inject_agent_memory", "text_de": "Ein Träger sprach {agent} ein Idiom aus einer anderen Welt vor. {agent} versteht es nicht, und kann es trotzdem nicht mehr vergessen.", "text_en": "A courier spoke {agent} an idiom from another world. {agent} does not understand it, and still cannot forget it."}, {"impact_level": 3, "kind": "spawn_event", "text_de": "In {sim} ist eine Redewendung aus dem Drift angekommen. Sie hat hier noch keine Bedeutung, aber die Münder formen sie schon.", "text_en": "A turn of phrase from the Drift has reached {sim}. It has no meaning here yet, but the mouths are already shaping it.", "title_de": "Drift-Depesche · Geliehenes Idiom", "title_en": "Drift Dispatch · Borrowed Idiom"}], "prose": {"brief_de": "Eine Redewendung, für die es hier kein Wort gibt, will in eine Welt getragen werden, die sie noch nicht kennt.", "brief_en": "A turn of phrase with no word for it here wants carrying to a world that does not yet know it.", "title_de": "Depesche · Geliehenes Idiom", "title_en": "Dispatch · Borrowed Idiom"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET family = EXCLUDED.family, tier = EXCLUDED.tier, pack_slug = EXCLUDED.pack_slug, definition = EXCLUDED.definition;
INSERT INTO travel_quest_templates (template_key, family, tier, pack_slug, definition) VALUES ($DQ$deliver_dream_cargo$DQ$, $DQ$deliver$DQ$, 2, $DQ$drift_p0c_seed$DQ$, $JB${"cargo": {"family": "traumfracht", "vector": "dream"}, "effects": [{"kind": "emit_fragment", "text_de": "Ich habe Traumfracht über den Drift getragen. Sie wollte ständig woanders sein als in meinen Händen, und einmal träumte ich ihren Inhalt, statt ihn zu tragen.", "text_en": "I carried dream-freight across the Drift. It kept wanting to be anywhere but in my hands, and once I dreamed its contents instead of carrying them."}, {"kind": "emit_echo", "text_de": "Ein verklingendes Echo streift {sim}. Für einen Lidschlag träumt die Stadt etwas, das ihr nicht gehört.", "text_en": "A fading echo brushes {sim}. For the space of a blink the city dreams something that is not its own.", "title_de": "Echo aus dem Drift", "title_en": "Echo from the Drift"}, {"importance": 4, "kind": "inject_agent_memory", "text_de": "Ein Träger überließ {agent} eine Traumfracht aus einer anderen Welt. {agent} wird heute Nacht etwas träumen, das jemand anderes erfunden hat.", "text_en": "A courier left {agent} a dream-freight from another world. Tonight {agent} will dream something that someone else invented."}, {"impact_level": 3, "kind": "spawn_event", "text_de": "In {sim} ist Traumfracht aus dem Drift eingetroffen. Am Rand des Schlafs sickert etwas Fremdes in die Welt.", "text_en": "Dream-freight from the Drift has arrived in {sim}. At the edge of sleep something foreign seeps into the world.", "title_de": "Drift-Depesche · Traumfracht", "title_en": "Drift Dispatch · Dream-Freight"}], "prose": {"brief_de": "Flüchtige Traumfracht, luzide und ungeduldig. Sie muss ankommen, bevor sie sich beim Wachwerden auflöst.", "brief_en": "Volatile dream-freight, lucid and impatient. It must arrive before waking dissolves it.", "title_de": "Depesche · Traumfracht", "title_en": "Dispatch · Dream-Freight"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET family = EXCLUDED.family, tier = EXCLUDED.tier, pack_slug = EXCLUDED.pack_slug, definition = EXCLUDED.definition;
INSERT INTO travel_quest_templates (template_key, family, tier, pack_slug, definition) VALUES ($DQ$deliver_memory_parcel$DQ$, $DQ$deliver$DQ$, 1, $DQ$drift_p0c_seed$DQ$, $JB${"cargo": {"family": "erinnerungsstuecke", "vector": "memory"}, "effects": [{"kind": "emit_fragment", "text_de": "Ich habe ein Erinnerungsstück über den Drift getragen. An der Schwelle wurde es kurz schwer, als wöge die fremde Erinnerung mehr als die eigene.", "text_en": "I carried a memory-relic across the Drift. At the threshold it grew briefly heavy, as if the borrowed memory weighed more than my own."}, {"kind": "emit_echo", "text_de": "Ein verklingendes Echo streift {sim}. Irgendwo in der Nähe hat eine Erinnerung, die nicht hierher gehört, die Schwelle berührt.", "text_en": "A fading echo brushes {sim}. Somewhere close, a memory that does not belong here has touched the threshold.", "title_de": "Echo aus dem Drift", "title_en": "Echo from the Drift"}, {"importance": 4, "kind": "inject_agent_memory", "text_de": "Ein Träger brachte {agent} ein Erinnerungsstück aus einer anderen Welt. Es zeigt einen Ort, den es hier nie gegeben hat, und doch kommt er bekannt vor.", "text_en": "A courier brought {agent} a memory-relic from another world. It shows a place that never existed here, and yet it feels familiar."}, {"impact_level": 3, "kind": "spawn_event", "text_de": "In {sim} ist ein Erinnerungsstück aus dem Drift eingetroffen. Wer es ansieht, erinnert sich an Dinge, die nie geschehen sind.", "text_en": "A memory-relic from the Drift has arrived in {sim}. Those who look at it remember things that never happened.", "title_de": "Drift-Depesche · Erinnerungsstück", "title_en": "Drift Dispatch · Memory-Relic"}], "prose": {"brief_de": "Ein Erinnerungsstück will über den Drift getragen werden, ein Gegenstand, der sich an einen anderen Ort erinnert.", "brief_en": "A memory-relic asks to be carried across the Drift, an object that remembers somewhere else.", "title_de": "Depesche · Erinnerungsstück", "title_en": "Dispatch · Memory-Relic"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET family = EXCLUDED.family, tier = EXCLUDED.tier, pack_slug = EXCLUDED.pack_slug, definition = EXCLUDED.definition;
INSERT INTO travel_quest_templates (template_key, family, tier, pack_slug, definition) VALUES ($DQ$deliver_sealed_contract$DQ$, $DQ$deliver$DQ$, 1, $DQ$drift_p0c_seed$DQ$, $JB${"cargo": {"family": "kontrakte", "vector": "commerce"}, "effects": [{"kind": "emit_fragment", "text_de": "Ich habe einen versiegelten Kontrakt über den Drift getragen. Solange das Wachs hielt, fühlte sich die Reise an wie eine Schuld, die ich noch nicht kannte.", "text_en": "I carried a sealed contract across the Drift. As long as the wax held, the journey felt like a debt I did not yet know I owed."}, {"kind": "emit_echo", "text_de": "Ein verklingendes Echo streift {sim}. Eine Unterschrift, die niemand hier geleistet hat, beginnt zu binden.", "text_en": "A fading echo brushes {sim}. A signature no one here ever made begins to bind.", "title_de": "Echo aus dem Drift", "title_en": "Echo from the Drift"}, {"importance": 4, "kind": "inject_agent_memory", "text_de": "Ein Träger legte {agent} einen versiegelten Kontrakt aus einer anderen Welt vor. Die Klauseln sind in einer Hand geschrieben, die {agent} zu kennen glaubt.", "text_en": "A courier presented {agent} a sealed contract from another world. Its clauses are written in a hand {agent} believes they recognise."}, {"impact_level": 3, "kind": "spawn_event", "text_de": "In {sim} wurde ein Kontrakt aus dem Drift eingelöst. Eine Abmachung gilt nun, die diese Welt nie geschlossen hat.", "text_en": "A contract from the Drift has been honored in {sim}. An agreement now holds that this world never made.", "title_de": "Drift-Depesche · Versiegelter Kontrakt", "title_en": "Drift Dispatch · Sealed Contract"}], "prose": {"brief_de": "Ein versiegelter Kontrakt sucht den Ort, an dem er eingelöst werden muss. Das Siegel darf erst am Ziel brechen.", "brief_en": "A sealed contract seeks the place where it must be honored. The seal may break only at its destination.", "title_de": "Depesche · Versiegelter Kontrakt", "title_en": "Dispatch · Sealed Contract"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET family = EXCLUDED.family, tier = EXCLUDED.tier, pack_slug = EXCLUDED.pack_slug, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$begegnung_havarist$DQ$, $DQ$begegnung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 14, "mid": 14, "near": 10}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"options": [{"cost": {"kh": 12}, "key": "kohaerenz_teilen", "label_de": "Kohärenz teilen", "label_en": "Share coherence", "result": {"deltas": {"dz": -3, "siegel": 8}, "text_de": "Der Träger gibt ab, was er hat, und der andere nimmt es, ohne zu danken, weil Danken hier draußen Zeit kostet, die keiner hat. Später wird jemand darüber reden, dass es einen gibt, der teilt.", "text_en": "The courier gives what they have, and the other takes it without thanks, because out here thanks costs time no one has. Later, someone will mention that there is one who shares."}}, {"check": {"difficulty": 6, "vector": "commerce"}, "failure": {"deltas": {"cargo_grant": {"family": "sehnsuchtsgut", "haul": 4, "vector": "desire"}, "dz": 5}, "text_de": "Der andere versteht das Angebot als das, was es zur Hälfte ist. Er gibt die Fracht her und sieht dabei weg, und der Blick bleibt am Träger hängen wie ein Widerhaken.", "text_en": "The other understands the offer for the half of it that it is. They hand the freight over looking away, and the look catches on the courier like a barb."}, "key": "fracht_kaufen", "label_de": "Sein Manifest abkaufen", "label_en": "Buy their manifest", "success": {"deltas": {"cargo_grant": {"family": "sehnsuchtsgut", "haul": 4, "vector": "desire"}}, "text_de": "Sie einigen sich, schnell und ohne Groll. Der andere reist leicht weiter, der Träger schwer, und beide halten das für den besseren Teil.", "text_en": "They come to terms, quickly and without rancour. The other travels on light, the courier heavy, and both consider theirs the better half of the deal."}}, {"key": "weiterfahren", "label_de": "Weiterfahren", "label_en": "Travel on", "result": {"deltas": {"dz": 2}, "text_de": "Der Träger fährt weiter. Es ist die vernünftige Entscheidung, und sie hallt genau so lange nach, wie das Fenster noch offen steht.", "text_en": "The courier travels on. It is the sensible decision, and it echoes for exactly as long as the window stays open."}}], "prose": {"body_de": "Ein Träger, angeschlagen bis zur Durchsichtigkeit, sitzt auf seinem Manifest wie auf einem Koffer am falschen Bahnsteig. Er bittet nicht. Er sieht nur her, und das reicht.", "body_en": "A courier, battered to the point of transparency, sits on their manifest like a suitcase on the wrong platform. They do not ask. They only look over, and that is enough.", "title_de": "Havarist", "title_en": "Castaway"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$begegnung_pruefer$DQ$, $DQ$begegnung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 4, "mid": 10, "near": 16}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"options": [{"cost": {"takt": 1}, "key": "vorlegen", "label_de": "Manifest vorlegen", "label_en": "Present the manifest", "result": {"deltas": {"siegel": 6}, "text_de": "Der Prüfer geht Zeile für Zeile durch, findet nichts, und sieht darüber beinahe enttäuscht aus. Dann stempelt er, sorgfältig, in die Luft.", "text_en": "The examiner goes through it line by line, finds nothing, and looks almost disappointed about it. Then they stamp, meticulously, into the air."}}, {"check": {"difficulty": 7, "vector": "language"}, "failure": {"deltas": {"dz": 3, "takt": -1}, "text_de": "Der Prüfer kennt die Vorschrift. Er kennt auch die, die sie aufgehoben hat. Die Nachprüfung dauert, und sie steht dem Träger ins Gesicht geschrieben.", "text_en": "The examiner knows the regulation. They also know the one that repealed it. The follow-up inspection takes time, and it is written all over the courier's face."}, "key": "berufen", "label_de": "Sich auf die Dienstvorschrift berufen", "label_en": "Cite the standing orders", "success": {"deltas": {"dz": -2}, "text_de": "Der Träger zitiert eine Vorschrift, die es geben müsste, und der Prüfer nickt, weil es sie geben müsste. Man trennt sich mit gegenseitigem Respekt vor der Verwaltung.", "text_en": "The courier cites a regulation that ought to exist, and the examiner nods, because it ought to. They part with a shared respect for administration."}}], "prose": {"body_de": "Ein Prüfer des Büros, mitten im Drift, mit einer Klemmmappe und einer Ruhe, die entweder Dienstalter ist oder Wahnsinn. Er möchte das Manifest sehen. Er hat sichtlich Zeit.", "body_en": "A Bureau examiner, in the middle of the Drift, with a clipboard and a calm that is either seniority or madness. They would like to see the manifest. They evidently have time.", "title_de": "Prüfer im Feld", "title_en": "Field Examiner"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$begegnung_spiegelgaenger$DQ$, $DQ$begegnung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 18, "mid": 10, "near": 4}$JB$::jsonb, $JB${"dz_band": ["erhoeht", "kritisch"]}$JB$::jsonb, $JB${"options": [{"check": {"difficulty": 9, "vector": "memory"}, "failure": {"deltas": {"dz": 4, "kh": -12}, "text_de": "Der Träger grüßt zurück, und der Spiegelgänger erwidert perfekt. Für einen Moment ist nicht mehr entscheidbar, wer von beiden geübt hat.", "text_en": "The courier returns the greeting, and the mirror-walker answers perfectly. For a moment it is no longer decidable which of the two was practising."}, "key": "gruessen", "label_de": "Zurückgrüßen", "label_en": "Return the greeting", "success": {"deltas": {"dz": -8}, "text_de": "Der Träger grüßt zurück, mit einer Geste, die nur er kennen kann, weil sie aus einer Erinnerung stammt, die er niemandem erzählt hat. Der Spiegelgänger kann sie nicht erwidern und löst sich auf, höflich, fast erleichtert.", "text_en": "The courier returns the greeting with a gesture only they can know, because it comes from a memory they have told no one. The mirror-walker cannot answer it and dissolves, politely, almost relieved."}}, {"cost": {"kh": 4, "takt": 1}, "key": "ausweichen", "label_de": "Ausweichen", "label_en": "Step aside", "result": {"deltas": {}, "text_de": "Der Träger geht einen weiten Bogen und sieht nicht hin. Der Spiegelgänger geht denselben Bogen, spiegelverkehrt, und sieht ebenfalls nicht hin.", "text_en": "The courier takes a wide arc and does not look. The mirror-walker takes the same arc, reversed, and does not look either."}}], "prose": {"body_de": "Jemand kommt entgegen, der geht wie der Träger geht, und trägt, was der Träger trägt. Er hebt die Hand zum Gruß einen Augenblick zu früh, als hätte er die Geste geübt und nicht gelernt.", "body_en": "Someone comes the other way who walks as the courier walks and carries what the courier carries. They raise a hand in greeting a moment too early, as though they had practised the gesture rather than learned it.", "title_de": "Spiegelgänger", "title_en": "Mirror-Walker"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$fund_bandbreitenader$DQ$, $DQ$fund$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 12, "mid": 14, "near": 10}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"bb": 2}, "text_de": "Der Träger zapft an, so lange es geht. Die Ader versiegt, kaum dass sie gemerkt hat, dass jemand trinkt.", "text_en": "The courier taps in for as long as it lasts. The vein runs dry almost as soon as it notices someone drinking."}, "prose": {"body_de": "Eine Ader offener Bandbreite, dick wie ein Seil, aus keiner erkennbaren Quelle. Sie liegt einfach da, wie Wasser in einer Wüste, die nicht dafür bekannt ist.", "body_en": "A vein of open bandwidth, thick as a rope, from no discernible source. It simply lies there, like water in a desert not known for it.", "title_de": "Bandbreitenader", "title_en": "Bandwidth Vein"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$fund_peilprotokoll$DQ$, $DQ$fund$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 10, "mid": 12, "near": 10}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"rumor_reveal": {}, "siegel": 3}, "text_de": "Der Träger übernimmt die Peilungen ins eigene Logbuch. Ein Knoten, den bisher niemand hier verzeichnet hat, hat auf einmal eine Adresse.", "text_en": "The courier copies the bearings into their own log. A node no one here had charted suddenly has an address."}, "prose": {"body_de": "Ein Protokoll fremder Peilungen, mit einer Handschrift, die zum Schluss hin ruhiger wird statt hektischer. Die letzten Einträge sind sehr genau.", "body_en": "A log of someone else's bearings, in a hand that grows calmer towards the end rather than more frantic. The final entries are very precise.", "title_de": "Peilprotokoll", "title_en": "Bearing Log"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$fund_schwere_bergung$DQ$, $DQ$fund$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 12, "mid": 12, "near": 8}$JB$::jsonb, $JB${"kh_band": ["angeschlagen", "intakt"]}$JB$::jsonb, $JB${"auto": {"deltas": {"cargo_grant": {"family": "blaupausen", "haul": 5, "vector": "architecture"}, "kh": -4}, "text_de": "Der Träger nimmt sie auf. Der Rumpf ächzt einmal, kurz und sehr deutlich, und dann fährt man eben schwerer.", "text_en": "The courier takes it aboard. The hull groans once, briefly and very clearly, and from here one simply travels heavier."}, "prose": {"body_de": "Etwas Großes, Wertvolles und Unbequemes. Es passt nicht gut in das Manifest und es lässt sich auch nicht gut liegen lassen, und der Träger weiß beides, während er zugreift.", "body_en": "Something large, valuable and inconvenient. It does not fit the manifest well and it does not sit well being left behind, and the courier knows both while reaching for it.", "title_de": "Schwere Bergung", "title_en": "Heavy Salvage"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$fund_siegelkassette$DQ$, $DQ$fund$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 18, "mid": 10, "near": 2}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"siegel": 14}, "text_de": "Der Träger zählt nach, zweimal, und schreibt sich die Kassette gut. Wer sie verloren hat, wird nicht mehr danach fragen.", "text_en": "The courier counts twice and books the casket to their own ledger. Whoever lost it will not be asking after it."}, "prose": {"body_de": "Eine Kassette des Büros, tief im Drift, mit einer Prägung, die seit Jahren nicht mehr vergeben wird. Das Schloss ist offen. Der Inhalt ist vollzählig.", "body_en": "A Bureau casket, deep in the Drift, stamped with a mark that has not been issued for years. The lock is open. The contents are complete.", "title_de": "Siegelkassette", "title_en": "Seal Casket"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$fund_stilles_wasser$DQ$, $DQ$fund$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 8, "mid": 10, "near": 12}$JB$::jsonb, $JB${"kh_band": ["kritisch", "angeschlagen"]}$JB$::jsonb, $JB${"auto": {"deltas": {"dz": -2, "kh": 14}, "text_de": "Der Träger hält an, länger als er müsste, und lässt sich zusammenlaufen. Es ist kein Vermögen. Es ist der Grund, warum man ankommt.", "text_en": "The courier stops, longer than necessary, and lets themselves run back together. It is not a fortune. It is the reason one arrives at all."}, "prose": {"body_de": "Eine Stelle, an der der Drift nicht zieht. Kein Fund im Sinne des Büros, nichts, was man abliefern könnte. Nur eine Handbreit Ruhe, die niemandem gehört.", "body_en": "A place where the Drift does not pull. No find in the Bureau's sense, nothing one could deliver. Just a hand's breadth of calm that belongs to no one.", "title_de": "Stilles Wasser", "title_en": "Still Water"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$fund_traumnest$DQ$, $DQ$fund$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 14, "mid": 12, "near": 6}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"cargo_grant": {"family": "traumfracht", "haul": 4, "vector": "dream"}, "dz": 2}, "text_de": "Der Träger packt ein, so vorsichtig es geht. Etwas im Nest träumt jetzt von ihm, und der Drift hört zu.", "text_en": "The courier packs it, as carefully as possible. Something in the nest now dreams of them, and the Drift is listening."}, "prose": {"body_de": "Ein Nest aus Traumfracht, ineinander verhakt wie schlafende Tiere. Es gehört niemandem und es ist etwas wert und es träumt weiter, während man es einpackt.", "body_en": "A nest of dream-freight, hooked into itself like sleeping animals. It belongs to no one and it is worth something and it keeps dreaming while one packs it.", "title_de": "Traumnest", "title_en": "Dream Nest"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$fund_verwaiste_sendung$DQ$, $DQ$fund$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 12, "mid": 16, "near": 12}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"cargo_grant": {"family": "kontrakte", "haul": 2, "vector": "commerce"}}, "text_de": "Der Träger nimmt die Sendung auf und trägt sie weiter, weil das die Antwort des Büros auf alles ist, was liegen bleibt.", "text_en": "The courier takes the consignment aboard and carries it on, because that is the Bureau's answer to everything left lying."}, "prose": {"body_de": "Eine Sendung ohne Träger, sauber verzurrt, das Siegel intakt. Wer sie hierher gebracht hat, ist nicht weitergekommen, und hat vorher noch ordentlich gepackt.", "body_en": "A consignment without a courier, neatly lashed, seal intact. Whoever brought it here did not get further, and packed carefully before they stopped.", "title_de": "Verwaiste Sendung", "title_en": "Orphaned Consignment"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$geruecht_fremdpeilung$DQ$, $DQ$geruecht$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 10, "mid": 14, "near": 14}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"rumor_reveal": {}}, "text_de": "Der Träger schreibt mit. Der Kanal wiederholt die Peilung noch zweimal und schweigt dann, zufrieden oder erschöpft.", "text_en": "The courier writes it down. The channel repeats the bearing twice more and then falls silent, satisfied or exhausted."}, "prose": {"body_de": "Auf einem Kanal, der eigentlich leer sein müsste, wiederholt jemand eine Peilung. Immer dieselbe, in immer denselben Abständen, als hoffe er noch, dass jemand sie mitschreibt.", "body_en": "On a channel that ought to be empty, someone repeats a bearing. Always the same one, always at the same interval, as if still hoping someone is writing it down.", "title_de": "Fremdpeilung", "title_en": "Foreign Bearing"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$geruecht_grabungsnotiz$DQ$, $DQ$geruecht$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 10, "mid": 16, "near": 8}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"rumor_reveal": {"band": "mid"}}, "text_de": "Der Träger trägt Knoten und Zahl ein. Die zweite Zahl ist die wichtigere, und sie steht nicht dabei.", "text_en": "The courier charts the node and the count. The second number is the one that matters, and it is not written down."}, "prose": {"body_de": "Eine Notiz über eine Sondierung, die jemand abgebrochen hat, kurz bevor sie sich gelohnt hätte. Die Notiz nennt den Knoten und sagt, wie oft dort schon gegraben wurde. Sie sagt nicht, warum abgebrochen wurde.", "body_en": "A note on an excavation someone abandoned just before it would have paid. The note names the node and says how often it has been dug. It does not say why they stopped.", "title_de": "Grabungsnotiz", "title_en": "Excavation Note"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$geruecht_hafenklatsch$DQ$, $DQ$geruecht$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 4, "mid": 10, "near": 18}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"rumor_reveal": {}}, "text_de": "Der Träger notiert den Ort, so wie man einen Namen notiert, den man auf einer Feier gehört hat und morgen brauchen wird.", "text_en": "The courier notes the place down, the way one notes a name heard at a party and needed tomorrow."}, "prose": {"body_de": "Klatsch aus der Nähe von {sim}: Man rede dort über eine Sendung, die nie angekommen sei, und über den Ort, an dem sie zuletzt gesehen wurde. Der Ort steht auf keiner Karte des Büros.", "body_en": "Talk from near {sim}: they speak of a consignment that never arrived, and of the place where it was last seen. The place is on no Bureau chart.", "title_de": "Hafenklatsch", "title_en": "Harbour Talk"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$geruecht_maerkte$DQ$, $DQ$geruecht$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 6, "mid": 12, "near": 12}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"siegel": 5}, "text_de": "Der Träger meldet das Gerücht weiter, wie es die Dienstvorschrift verlangt, und das Büro zahlt die kleine Prämie, die es für Ohren zahlt.", "text_en": "The courier passes the rumour on, as the standing orders require, and the Bureau pays the small premium it pays for ears."}, "prose": {"body_de": "Ein Kursgerücht, wie es sie zu Hunderten gibt, nur dass dieses eine Zahl nennt und eine Frist. In {sim} wird jemand sehr genau zugehört haben.", "body_en": "A price rumour, of the kind that exists by the hundred, except this one names a figure and a deadline. In {sim}, someone will have been listening very closely.", "title_de": "Marktgerücht", "title_en": "Market Rumour"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$geruecht_nachruf$DQ$, $DQ$geruecht$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 12, "mid": 12, "near": 8}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"dz": 3, "rumor_reveal": {}}, "text_de": "Der Träger hört zu Ende und trägt den Knoten ein, den der Nachruf erwähnt. Man hört sich seinen eigenen Nachruf nicht ohne Kosten an.", "text_en": "The courier listens to the end and charts the node the obituary mentions. One does not listen to one's own obituary for free."}, "prose": {"body_de": "Ein Nachruf auf einen Träger, den es nach den Akten nie gegeben hat, gesendet auf einer Frequenz, die dem Träger auffällig gut liegt. Der Nachruf ist warm. Er ist auch sehr detailliert.", "body_en": "An obituary for a courier who, by the records, never existed, broadcast on a frequency that suits this courier uncomfortably well. The obituary is warm. It is also very detailed.", "title_de": "Nachruf", "title_en": "Obituary"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$geruecht_relaisruf$DQ$, $DQ$geruecht$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 10, "mid": 14, "near": 12}$JB$::jsonb, $JB${"kh_band": ["kritisch", "angeschlagen"]}$JB$::jsonb, $JB${"auto": {"deltas": {"rumor_reveal": {"band": "near"}}, "text_de": "Der Träger nimmt die Position auf. Es ist kein Zuhause. Aber es ist ein Ort, der antwortet, und das ist hier draußen fast dasselbe.", "text_en": "The courier takes down the position. It is not home. But it is a place that answers, and out here that is nearly the same thing."}, "prose": {"body_de": "Ein Relais ruft in die Leere und sagt seine Position, wieder und wieder, wie ein Leuchtturm, der nicht weiß, ob es noch Schiffe gibt. Angeschlagen hört man solche Rufe deutlicher.", "body_en": "A relay calls into the void, giving its position again and again, like a lighthouse unsure whether ships still exist. Battered, one hears such calls more clearly.", "title_de": "Relaisruf", "title_en": "Relay Call"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$geruecht_tiefenmeldung$DQ$, $DQ$geruecht$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 18, "mid": 10, "near": 2}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"rumor_reveal": {"band": "deep"}}, "text_de": "Der Träger trägt den Knoten ein. Ob der Sprecher noch dort steht, wird sich zeigen, wenn jemand hinfährt.", "text_en": "The courier charts the node. Whether the speaker is still standing on it will become clear when someone goes."}, "prose": {"body_de": "Eine Meldung aus der Tiefe, in der Formsprache des Büros, aber mit einem Rufzeichen, das seit Jahren nicht mehr vergeben wird. Sie beschreibt einen Knoten so genau, als stünde der Sprecher darauf.", "body_en": "A report from the deep, in the Bureau's own phrasing, but with a call sign that has not been issued in years. It describes a node so precisely that the speaker must be standing on it.", "title_de": "Tiefenmeldung", "title_en": "Deep Report"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stille_ruhige_passage$DQ$, $DQ$stille$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 10, "mid": 16, "near": 20}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"dz": -1}, "text_de": "Eine ruhige Passage. Der Träger nutzt sie, wie man eine ruhige Passage nutzt: er wird ein wenig ruhiger.", "text_en": "A quiet passage. The courier uses it the way one uses a quiet passage: they become a little quieter themselves."}, "prose": {"body_de": "Nichts. Der Drift steht offen und desinteressiert, und die Instrumente haben nichts zu melden.", "body_en": "Nothing. The Drift lies open and uninterested, and the instruments have nothing to report.", "title_de": "Ruhige Passage", "title_en": "Quiet Passage"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stille_totwasser$DQ$, $DQ$stille$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 20, "mid": 10, "near": 4}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"dz": 1}, "text_de": "Der Träger fährt hindurch und hört sich selbst dabei zu, wie er nichts hört. Man kommt aus solchen Passagen nicht ruhiger heraus, als man hineingefahren ist.", "text_en": "The courier passes through and listens to themselves hearing nothing. One does not come out of such passages calmer than one went in."}, "prose": {"body_de": "Eine Stille, die nicht leer ist, sondern geräumt. Etwas hat hier aufgehört zu senden, und es hat vorher aufgeräumt.", "body_en": "A silence that is not empty but cleared. Something stopped broadcasting here, and tidied up before it did.", "title_de": "Totwasser", "title_en": "Dead Water"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stille_wartungsfenster$DQ$, $DQ$stille$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 10, "mid": 14, "near": 14}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"auto": {"deltas": {"kh": 3}, "text_de": "Der Träger zieht nach, was sich gelockert hat. Es ist keine Reparatur. Es ist der Unterschied zwischen einer Reparatur und einer Havarie.", "text_en": "The courier tightens what has worked loose. It is not a repair. It is the difference between a repair and a Havarie."}, "prose": {"body_de": "Kein Signal, keine Peilung, keine Gegenstimme. Nur der eigene Rumpf, der leise arbeitet, und Zeit, ihm zuzuhören.", "body_en": "No signal, no bearing, no countervoice. Only one's own hull working quietly, and time to listen to it.", "title_de": "Wartungsfenster", "title_en": "Maintenance Window"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stoerung_bandbreitenfrass$DQ$, $DQ$stoerung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 10, "mid": 12, "near": 8}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"options": [{"cost": {"kh": 8}, "key": "abschirmen", "label_de": "Kanal abschirmen", "label_en": "Shield the channel", "result": {"deltas": {"bb": 1}, "text_de": "Der Träger legt die eigene Kohärenz um den Kanal wie einen Mantel um ein Kind. Der Fraß findet nichts mehr zu beißen und zieht weiter.", "text_en": "The courier wraps their own coherence around the channel like a coat around a child. The rot finds nothing left to bite and moves on."}}, {"check": {"difficulty": 6, "vector": "resonance"}, "failure": {"deltas": {"bb": -2, "dz": 2}, "text_de": "Der Fraß ist nicht satt zu bekommen. Als er weiterzieht, fehlt der Anlage ein Stück, das keine Werkstatt im Drift ersetzt.", "text_en": "The rot cannot be sated. When it moves on, the rig is missing a piece no workshop in the Drift will replace."}, "key": "aussitzen", "label_de": "Fraß aussitzen", "label_en": "Sit the rot out", "success": {"deltas": {"dz": 1}, "text_de": "Der Träger wartet, bis der Fraß satt ist. Er ist früher satt als erwartet, und was er zurücklässt, schwingt sauberer als vorher.", "text_en": "The courier waits until the rot is sated. It is sated sooner than expected, and what it leaves behind rings cleaner than before."}}], "prose": {"body_de": "Etwas frisst an der Bandbreite. Nicht laut, nicht schnell, sondern mit der Geduld von Rost. Die Anzeige verliert eine Stelle, dann noch eine.", "body_en": "Something is eating the bandwidth. Not loudly, not fast, but with the patience of rust. The gauge loses a digit, then another.", "title_de": "Bandbreitenfraß", "title_en": "Bandwidth Rot"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stoerung_echofracht$DQ$, $DQ$stoerung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 10, "mid": 10, "near": 6}$JB$::jsonb, $JB${"kh_band": ["intakt"]}$JB$::jsonb, $JB${"options": [{"check": {"difficulty": 8, "vector": "memory"}, "failure": {"deltas": {"dz": 3, "kh": -11}, "text_de": "Es ist ein Köder. Das Siegel löst sich auf, sobald es an Bord ist, und was darunter lag, hat auf Gesellschaft gewartet.", "text_en": "It is bait. The seal dissolves the moment it is aboard, and what lay beneath it had been waiting for company."}, "key": "bergen", "label_de": "Bergen", "label_en": "Take it aboard", "success": {"deltas": {"cargo_grant": {"family": "erinnerungsstuecke", "haul": 3, "vector": "memory"}}, "text_de": "Es ist eine Bergung. Der Träger nimmt sie auf, und das Siegel gehört tatsächlich zu einem Büro, das noch antwortet.", "text_en": "It is salvage. The courier takes it aboard, and the seal does belong to a bureau that still answers."}}, {"key": "treiben_lassen", "label_de": "Treiben lassen", "label_en": "Let it drift on", "result": {"deltas": {"dz": 1}, "text_de": "Der Träger lässt es ziehen und sieht ihm nach, länger als nötig. Der Drift ist voll von Sendungen, die niemand abgeholt hat. Eine mehr.", "text_en": "The courier lets it go and watches it longer than necessary. The Drift is full of consignments no one collected. One more."}}], "prose": {"body_de": "Etwas treibt heran, das aussieht wie eine Sendung und sich anfühlt wie ein Echo. Es hat ein Siegel, das der Träger fast kennt. Es ist entweder eine Bergung oder ein Köder, und es sieht in beiden Fällen gleich aus.", "body_en": "Something drifts up that looks like a consignment and feels like an echo. It carries a seal the courier almost recognises. It is either salvage or bait, and it looks the same either way.", "title_de": "Echofracht", "title_en": "Echo Freight"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stoerung_fensterzug$DQ$, $DQ$stoerung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 6, "mid": 10, "near": 12}$JB$::jsonb, $JB${"window_band": ["knapp"]}$JB$::jsonb, $JB${"options": [{"check": {"difficulty": 7, "vector": "desire"}, "failure": {"deltas": {"dz": 2, "takt": -1}, "text_de": "Eile ist keine Geschwindigkeit. Der Träger verliert am Ende genau die Zeit, die er sich nehmen wollte, und dazu ein Stück Ruhe.", "text_en": "Haste is not speed. In the end the courier loses exactly the time they meant to take, and a piece of their calm on top."}, "key": "hetzen", "label_de": "Dem Zug nachgeben", "label_en": "Give in to the draft", "success": {"deltas": {"takt": 1}, "text_de": "Der Träger wird schneller, ohne unsauber zu werden. Der Zug trägt ihn. Für einen Takt fühlt sich Eile an wie Können.", "text_en": "The courier speeds up without going ragged. The draft carries them. For one Takt, haste feels like skill."}}, {"cost": {"kh": 6}, "key": "verankern", "label_de": "Sich verankern", "label_en": "Anchor yourself", "result": {"deltas": {"dz": -2}, "text_de": "Der Träger stellt sich quer in den Zug und wartet, bis das Fenster wieder ein Fenster ist und keine Tür. Es kostet Substanz, ruhig zu bleiben.", "text_en": "The courier stands crosswise in the draft and waits until the window is a window again and not a door. Staying calm costs substance."}}], "prose": {"body_de": "Das Aufenthaltsfenster steht nicht mehr still. Es zieht, wie eine Tür zieht, die jemand am anderen Ende des Ganges geöffnet hat. Alles im Träger will schneller werden.", "body_en": "The permit window will not hold still. It draws, the way a door draws when someone opens another at the far end of the corridor. Everything in the courier wants to hurry.", "title_de": "Fensterzug", "title_en": "Window Draft"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stoerung_frachtunruhe$DQ$, $DQ$stoerung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 8, "mid": 10, "near": 10}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"options": [{"check": {"difficulty": 6, "vector": "dream"}, "failure": {"deltas": {"dz": 2, "kh": -9}, "text_de": "Die Fracht glaubt kein Wort. Sie verlagert sich gegen die Fahrtrichtung, und der Träger trägt ab jetzt gegen sie an.", "text_en": "The freight believes not a word. It shifts against the direction of travel, and from here the courier carries against it."}, "key": "beruhigen", "label_de": "Fracht beruhigen", "label_en": "Settle the freight", "success": {"deltas": {"kh": -2}, "text_de": "Der Träger erzählt der Fracht, wohin sie kommt, und macht es gut klingen. Sie glaubt es. Fracht ist leichtgläubig, wenn man ihr zuhört.", "text_en": "The courier tells the freight where it is going and makes it sound good. It believes them. Freight is credulous when it is listened to."}}, {"cost": {"bb": 1}, "key": "festzurren", "label_de": "Festzurren", "label_en": "Lash it down", "result": {"deltas": {"kh": -1}, "text_de": "Der Träger zurrt die Fracht mit Bandbreite fest, weil es das Einzige ist, was hier lang genug hält. Sie schweigt. Sie ist nicht überzeugt.", "text_en": "The courier lashes the freight down with bandwidth, because it is the only thing out here that holds long enough. It goes quiet. It is not convinced."}}], "prose": {"body_de": "Die Fracht wird unruhig. Sie hat gemerkt, wohin sie gebracht wird, und sie ist anderer Meinung. Frequenzgeformte Materie hat keine Stimme, aber sie hat Gewicht, und Gewicht kann man verlagern.", "body_en": "The freight grows restless. It has understood where it is being taken and disagrees. Frequency-shaped matter has no voice, but it has weight, and weight can shift.", "title_de": "Frachtunruhe", "title_en": "Freight Unrest"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stoerung_frequenzscherung$DQ$, $DQ$stoerung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 22, "mid": 10, "near": 4}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"options": [{"check": {"difficulty": 7, "vector": "architecture"}, "failure": {"deltas": {"dz": 3, "kh": -12}, "text_de": "Die Naht schließt sich schneller als der Träger sie halten kann. Was durchkommt, ist vollständig, aber es klingt, als wäre es zweimal gefaltet worden.", "text_en": "The seam closes faster than the courier can hold it. What comes through is complete, but it rings like something folded twice."}, "key": "durchdruecken", "label_de": "Durch die Scherung drücken", "label_en": "Push through the shear", "success": {"deltas": {"kh": -4}, "text_de": "Der Träger legt sich in die Naht wie in eine Tür und hält sie auf, bis die beiden Hälften wieder dieselbe Sprache sprechen. Die Instrumente einigen sich auf eine Position.", "text_en": "The courier leans into the seam like a door and holds it open until the two halves speak the same language again. The instruments settle on one position."}}, {"cost": {"takt": 1}, "key": "treiben_lassen", "label_de": "Treiben lassen, bis die Scherung ausläuft", "label_en": "Drift until the shear runs out", "result": {"deltas": {"dz": 2}, "text_de": "Der Träger hört auf zu steuern und lässt sich von der Scherung tragen, wie man sich von einem Streit tragen lässt, den man nicht führen will. Es kostet Zeit. Es kostet keine Substanz.", "text_en": "The courier stops steering and lets the shear carry them, the way one lets an argument one refuses to have carry one along. It costs time. It costs no substance."}}], "prose": {"body_de": "Die Trägerfrequenz reißt in zwei Hälften, die einander nicht mehr kennen. Für einen Moment steht der Träger in beiden und in keiner. Die Instrumente zeigen zwei Positionen an, beide plausibel.", "body_en": "The carrier frequency tears into two halves that no longer know each other. For a moment the courier stands in both and in neither. The instruments report two positions, both plausible.", "title_de": "Frequenzscherung", "title_en": "Frequency Shear"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stoerung_gegenstimme$DQ$, $DQ$stoerung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 14, "mid": 10, "near": 5}$JB$::jsonb, $JB${"dz_band": ["erhoeht", "kritisch"]}$JB$::jsonb, $JB${"options": [{"check": {"difficulty": 8, "vector": "language"}, "failure": {"deltas": {"dz": 4, "kh": -6}, "text_de": "Der Träger antwortet, und die Stimme antwortet zurück, besser. Das Gespräch dauert länger, als es dürfte.", "text_en": "The courier answers, and the voice answers back, better. The conversation lasts longer than it should."}, "key": "antworten", "label_de": "Der Stimme antworten", "label_en": "Answer the voice", "success": {"deltas": {"dz": -6}, "text_de": "Der Träger antwortet in einer Grammatik, die die Stimme nicht kennt. Sie verstummt beleidigt, und mit ihr ein Teil des Lärms, den sie mitgebracht hat.", "text_en": "The courier answers in a grammar the voice does not know. It falls silent, affronted, and takes part of the noise it brought with it."}}, {"key": "schweigen", "label_de": "Schweigen", "label_en": "Say nothing", "result": {"deltas": {"dz": 2, "kh": -2}, "text_de": "Der Träger schweigt, wie man in einem leeren Haus schweigt, in dem etwas mitgeht. Die Stimme redet weiter. Man gewöhnt sich, und das ist die eigentliche Kosten.", "text_en": "The courier says nothing, the way one says nothing in an empty house where something walks along. The voice keeps talking. One gets used to it, and that is the real cost."}}], "prose": {"body_de": "Die Dissonanz hat eine Stimme bekommen. Sie spricht mit dem Timbre des Trägers und sagt Sätze, die der Träger fast gesagt hätte. Sie ist plausibel. Das ist das Schlimme.", "body_en": "The dissonance has found a voice. It speaks in the courier's timbre and says sentences the courier almost said. It is plausible. That is the bad part.", "title_de": "Gegenstimme", "title_en": "Countervoice"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stoerung_kartenfehler$DQ$, $DQ$stoerung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 18, "mid": 8, "near": 0}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"options": [{"check": {"difficulty": 8, "vector": "architecture"}, "cost": {"takt": 1}, "failure": {"deltas": {"dz": 3, "kh": -13}, "text_de": "Die Karte gewinnt. Für einen Moment ist der Träger das, was die Karte sagt: nichts. Es geht vorbei. Es geht nicht spurlos vorbei.", "text_en": "The chart wins. For a moment the courier is what the chart says: nothing. It passes. It does not pass without a trace."}, "key": "nachvermessen", "label_de": "Nachvermessen", "label_en": "Re-survey it", "success": {"deltas": {"rumor_reveal": {}, "siegel": 6}, "text_de": "Der Träger vermisst gegen die Karte an und gewinnt. Was hier steht, steht ab jetzt auch dort, wo man es nachlesen kann.", "text_en": "The courier surveys against the chart and wins. What stands here now stands where it can be read as well."}}, {"cost": {"kh": 5, "takt": 1}, "key": "umgehen", "label_de": "Fehler umgehen", "label_en": "Route around the error", "result": {"deltas": {}, "text_de": "Der Träger geht um den Fehler herum, wie man um ein Loch im Eis geht: weit, und ohne hinzusehen.", "text_en": "The courier routes around the error the way one routes around a hole in ice: widely, and without looking."}}], "prose": {"body_de": "Die Karte behauptet, hier sei nichts. Der Träger steht darin. Eines von beiden muss nachgeben, und die Karte hat den längeren Atem.", "body_en": "The chart insists there is nothing here. The courier is standing in it. One of the two must give way, and the chart has the longer breath.", "title_de": "Kartenfehler", "title_en": "Chart Error"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stoerung_manifestlast$DQ$, $DQ$stoerung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 6, "mid": 10, "near": 10}$JB$::jsonb, $JB${"overload": true}$JB$::jsonb, $JB${"options": [{"cost": {"takt": 1}, "key": "umschichten", "label_de": "Manifest umschichten", "label_en": "Restow the manifest", "result": {"deltas": {"kh": -2}, "text_de": "Der Träger ordnet die Ladung neu, bis sie wenigstens in dieselbe Richtung zieht wie er. Es ist Handarbeit, und Handarbeit kostet Fenster.", "text_en": "The courier restows the load until it at least pulls in the same direction as they do. It is handwork, and handwork costs window."}}, {"check": {"difficulty": 8, "vector": "commerce"}, "failure": {"deltas": {"dz": 3, "kh": -14}, "text_de": "Die Last gewinnt. Nichts geht verloren, aber der Träger zahlt jeden Meter zweimal, und der Drift schreibt mit.", "text_en": "The load wins. Nothing is lost, but the courier pays for every metre twice, and the Drift keeps the ledger."}, "key": "schleppen", "label_de": "Weiterschleppen", "label_en": "Haul on regardless", "success": {"deltas": {"kh": -5}, "text_de": "Der Träger schleppt und schleppt und kommt an. Der Rücken wird sich morgen melden. Das Manifest ist vollständig.", "text_en": "The courier hauls and hauls and arrives. The back will file its complaint tomorrow. The manifest is intact."}}], "prose": {"body_de": "Die Fracht ist zu viel für das, was der Träger ist. Sie zieht nicht am Rumpf, sie zieht am Träger selbst, und der Drift merkt es sofort, so wie Wasser einen Schwimmer merkt, der zu viel trägt.", "body_en": "The freight is more than the courier is. It does not pull at the hull, it pulls at the courier, and the Drift notices at once, the way water notices a swimmer carrying too much.", "title_de": "Manifestlast", "title_en": "Manifest Load"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stoerung_notfrequenzhusten$DQ$, $DQ$stoerung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 10, "mid": 12, "near": 10}$JB$::jsonb, $JB${"dz_band": ["erhoeht", "kritisch"], "kh_band": ["angeschlagen", "intakt"]}$JB$::jsonb, $JB${"options": [{"cost": {"takt": 1}, "key": "durchtakten", "label_de": "Frequenz durchtakten", "label_en": "Re-clock the band", "result": {"deltas": {"bb": 1, "dz": -3}, "text_de": "Der Träger taktet die Frequenz von Hand durch, Schlag für Schlag, bis sie wieder von selbst atmet. Es ist stumpfe Arbeit und sie hilft.", "text_en": "The courier re-clocks the band by hand, beat by beat, until it breathes on its own again. It is dull work and it helps."}}, {"check": {"difficulty": 7, "vector": "resonance"}, "failure": {"deltas": {"bb": -1, "kh": -10}, "text_de": "Sie fängt sich nicht. Zwischen zwei Schlägen ist nichts, und in diesem Nichts verliert der Träger etwas, das er nicht benennen kann.", "text_en": "It does not catch itself. Between two beats there is nothing, and in that nothing the courier loses something they cannot name."}, "key": "husten_lassen", "label_de": "Husten lassen", "label_en": "Let it cough", "success": {"deltas": {"dz": -1}, "text_de": "Der Träger lässt die Frequenz husten und fährt weiter. Sie fängt sich. Manche Dinge heilen, wenn man aufhört, an ihnen zu ziehen.", "text_en": "The courier lets the band cough and keeps moving. It catches itself. Some things heal when you stop pulling at them."}}], "prose": {"body_de": "Die Notfrequenz setzt aus und wieder ein, wie ein Husten, der nicht aufhören will. Jedes Aussetzen ist ein kurzer Blick darauf, wie es wäre, hier ohne sie zu sein.", "body_en": "The emergency band cuts out and back in, like a cough that will not stop. Every cut is a brief look at what it would be like to be out here without it.", "title_de": "Notfrequenzhusten", "title_en": "Emergency-Band Cough"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stoerung_rissfaenger$DQ$, $DQ$stoerung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 14, "mid": 12, "near": 6}$JB$::jsonb, $JB${"kh_band": ["kritisch", "angeschlagen"]}$JB$::jsonb, $JB${"options": [{"cost": {"bb": 1, "takt": 1}, "key": "kitten", "label_de": "Riss kitten", "label_en": "Seal the crack", "result": {"deltas": {"kh": 12}, "text_de": "Der Träger gibt Bandbreite her, um Substanz zu kaufen. Ein schlechter Kurs, aber der einzige, der hier angeboten wird.", "text_en": "The courier trades bandwidth for substance. A poor rate, and the only one on offer out here."}}, {"check": {"difficulty": 9, "vector": "memory"}, "failure": {"deltas": {"dz": 4, "kh": -15}, "text_de": "Der Riss wird ein Spalt. Der Träger sieht durch sich hindurch auf den Drift dahinter und wünschte, er hätte es nicht getan.", "text_en": "The crack becomes a gap. The courier looks through themselves at the Drift beyond and wishes they had not."}, "key": "ignorieren", "label_de": "Den Finger ignorieren", "label_en": "Ignore the finger", "success": {"deltas": {"dz": 1}, "text_de": "Der Träger erinnert sich, wer er war, bevor der Riss da war, und der Drift verliert das Interesse an einer Wunde, die ihr Träger nicht anerkennt.", "text_en": "The courier remembers who they were before the crack, and the Drift loses interest in a wound its bearer will not acknowledge."}}], "prose": {"body_de": "Der Drift hat den Riss gefunden, den der Träger mit sich trägt, und legt einen Finger hinein. Kein Angriff, eher Neugier. Neugier, die weiter aufmacht.", "body_en": "The Drift has found the crack the courier carries and lays a finger in it. Not an attack, more like curiosity. Curiosity that keeps opening.", "title_de": "Rissfänger", "title_en": "Crack-Catcher"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stoerung_statikschwarm$DQ$, $DQ$stoerung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 12, "mid": 12, "near": 8}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"options": [{"cost": {"bb": 1, "takt": 1}, "key": "erden", "label_de": "Knoten erden", "label_en": "Ground the node", "result": {"deltas": {"kh": -6}, "text_de": "Der Träger erdet den Knoten gegen sich selbst und nimmt die Ladung auf. Sie brennt, aber sie brennt in ihm und nicht in der Karte.", "text_en": "The courier grounds the node against themselves and takes the charge. It burns, but it burns in them and not in the chart."}}, {"key": "durchziehen_lassen", "label_de": "Schwarm durchziehen lassen", "label_en": "Let the swarm pass", "result": {"deltas": {"marker_add": "statik"}, "text_de": "Der Träger lässt den Schwarm ziehen. Er hinterlässt eine Ladung im Knoten, die dort bleiben wird, bis jemand sie ausgräbt oder sie jemanden findet.", "text_en": "The courier lets the swarm pass. It leaves a charge in the node that will stay there until someone digs it out, or it finds someone."}}, {"check": {"difficulty": 9, "vector": "resonance"}, "failure": {"deltas": {"kh": -8, "marker_add": "statik"}, "text_de": "Der Schwarm lässt sich anzapfen und zapft zurück. Was hier bleibt, gehört jetzt beiden.", "text_en": "The swarm allows the tap and taps back. What stays here now belongs to both."}, "key": "anzapfen", "label_de": "Ladung anzapfen", "label_en": "Tap the charge", "success": {"deltas": {"bb": 2, "dz": 2}, "text_de": "Der Träger zapft den Schwarm an, während er noch zieht. Die Bandbreite füllt sich mit fremder Energie, die sich sauber anfühlt und es nicht ist.", "text_en": "The courier taps the swarm while it is still passing. The bandwidth fills with borrowed energy that feels clean and is not."}}], "prose": {"body_de": "Ein Schwarm aus Statik zieht über den Knoten, dicht wie Regen und ebenso unpersönlich. Er lädt alles auf, was hier liegt, und was aufgeladen ist, lässt sich nicht mehr sauber vermessen.", "body_en": "A swarm of static crosses the node, dense as rain and just as impersonal. It charges everything lying here, and what is charged can no longer be surveyed cleanly.", "title_de": "Statikschwarm", "title_en": "Static Swarm"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
INSERT INTO travel_signal_templates (template_key, signal_class, pack_slug, band_weights, requires, definition) VALUES ($DQ$stoerung_zollschranke$DQ$, $DQ$stoerung$DQ$, $DQ$drift_w2_signals$DQ$, $JB${"deep": 0, "mid": 6, "near": 16}$JB$::jsonb, $JB${}$JB$::jsonb, $JB${"options": [{"cost": {"takt": 1}, "key": "ausfuellen", "label_de": "Formulare ausfüllen", "label_en": "Fill in the forms", "result": {"deltas": {"siegel": 2}, "text_de": "Der Träger füllt aus, unterschreibt, stempelt sich selbst ab. Der Balken hebt sich, langsam und würdevoll, für niemanden.", "text_en": "The courier fills in, signs, stamps themselves through. The bar rises, slow and dignified, for no one."}}, {"check": {"difficulty": 5, "vector": "commerce"}, "failure": {"deltas": {"dz": 5}, "text_de": "Das Büro ist nicht leer. Etwas notiert den Vorgang in einer Akte, die der Träger nie sehen wird, und der Drift wird ihn daran erinnern.", "text_en": "The bureau is not empty. Something records the incident in a file the courier will never see, and the Drift will remind them of it."}, "key": "unterfahren", "label_de": "Schranke unterfahren", "label_en": "Duck under the bar", "success": {"deltas": {"dz": 1}, "text_de": "Der Träger geht unten durch. Nichts passiert. Das Büro schweigt, wie Büros schweigen, wenn sie leer sind.", "text_en": "The courier goes under. Nothing happens. The bureau stays silent, the way bureaus are silent when they are empty."}}], "prose": {"body_de": "Eine Zollschranke im Nichts, gestellt von einem Büro, das es vielleicht nicht mehr gibt. Der Balken ist unten. Die Formulare sind echt. Irgendjemand hat sie ausgedruckt und dann alles verlassen.", "body_en": "A customs barrier in the middle of nowhere, put there by a bureau that may no longer exist. The bar is down. The forms are real. Someone printed them and then left everything behind.", "title_de": "Zollschranke", "title_en": "Customs Barrier"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET signal_class = EXCLUDED.signal_class, pack_slug = EXCLUDED.pack_slug, band_weights = EXCLUDED.band_weights, requires = EXCLUDED.requires, definition = EXCLUDED.definition;
